@startuml

class Car {
  + vehicleNumber : string
}

class Owner {
  + name : string
}

class Customer {
  + name : string
}

class RideHailService {
  + pickUpTime : datetime
  + dropOffTime : datetime
  + pickUpLocation : string
  + dropOffLocation : string
  + rideDuration : string
  + distance : float
  + numberOfPassengers : int
  + fee : double
  + requestType : string
}

class RideShareService {
  + pickUpTime : datetime
  + dropOffTime : datetime
  + pickUpLocation : string
  + dropOffLocation : string
  + rideDuration : string
  + distance : float
  + upfrontNegotiatedFee : double
}

class Accident {
  + date : date
  + location : string
  + damageAmount : double
}

class RideHailRequest {
  + leadCustomerName : string
}

class RideShareRequest {
  + customerNames : string[]
}

Car "0..*" -- "0..1" Owner : owned by
Car "1" -- "*" RideHailService : used for
Car "1" -- "*" RideShareService : used for
Car "1" -- "*" Accident : involved in
Customer "1" -- "*" RideHailService : uses
Customer "1" -- "*" RideShareService : uses
RideHailService "1" -- "1" RideHailRequest : has
RideShareService "1" -- "1" RideShareRequest : has

@enduml

